CREATE DATABASE IF NOT EXISTS nid_prototype CHARACTER SET utf8mb4;
USE nid_prototype;
CREATE TABLE offices(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(5) NOT NULL,name VARCHAR(120) NOT NULL,address VARCHAR(160),contact VARCHAR(40),available TINYINT DEFAULT 1);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,citizenship_number VARCHAR(30) NOT NULL UNIQUE,date_of_birth DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,application_number VARCHAR(20) UNIQUE,application_type ENUM('new_enrollment','replacement','correction') DEFAULT 'new_enrollment',status ENUM('submitted','verified','appointment_scheduled','biometric_pending','processing','card_ready','action_required') DEFAULT 'submitted',remarks VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE personal_details(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,full_name VARCHAR(100) NOT NULL,nepali_name VARCHAR(100),dob DATE NOT NULL,gender ENUM('male','female','other') NOT NULL,citizenship_district VARCHAR(60),birth_place VARCHAR(80),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE contact_details(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,mobile VARCHAR(10) NOT NULL,email VARCHAR(100),district VARCHAR(60),municipality VARCHAR(80),ward TINYINT,address VARCHAR(120),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,application_id INT NOT NULL,office_id INT NOT NULL,appointment_date DATE,appointment_time VARCHAR(10),token_number VARCHAR(20),FOREIGN KEY(application_id) REFERENCES applications(id),FOREIGN KEY(office_id) REFERENCES offices(id));
CREATE TABLE status_history(id INT AUTO_INCREMENT PRIMARY KEY,application_id INT NOT NULL,status VARCHAR(30),remarks VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES applications(id));
